+    private int countFeaturesWithTag(VectorTile.Tile.Layer layer, String tag, String value) {
+        int count = 0;
+        for (int i = 0; i < layer.getFeaturesCount(); i++) {
+            VectorTile.Tile.Feature feature = layer.getFeatures(i);
